  "name": "ferryx",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "tauri": "cargo tauri",
    "dev": "cargo tauri dev",
    "build": "cargo tauri build",
    "ui:dev": "bun run --cwd ui dev",
    "ui:test": "bun run --cwd ui test",
